package com.autocare.platform.order;

import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.service.MerchantActor;
import com.autocare.platform.vehicle.VehicleOwner;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Issuance only. Published terms and original issuing merchant never change. */
public class CouponInventory {
 final ReservationStore db;final OperatorIdentity operators;
 public CouponInventory(ReservationStore db,OperatorIdentity operators){this.db=db;this.operators=operators;}
 static ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"券状态、版本或库存已变化，请重新读取");}
 void manager(MerchantActor a,boolean lock){if(!a.manager())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"仅店长可管理本店券");db.merchant(a,lock);}
 static final String SELECT="SELECT c.*,s.project_id,s.terms_json,s.revision,s.pool_selected,s.pool_revision,p.revision AS publication_revision,p.terms_json AS published_terms FROM coupon c JOIN coupon_source s ON s.coupon_id=c.id LEFT JOIN coupon_publication p ON p.coupon_id=c.id";
 Map<String,Object> row(long id,boolean lock){return db.one(SELECT+" WHERE c.id=? AND c.is_deleted=0"+(lock?" FOR UPDATE":""),id);}
 void shopProject(long merchant,long project,boolean lock){String tail=lock?" FOR UPDATE":"";db.one("SELECT id FROM merchant WHERE id=? AND status=1 AND is_deleted=0"+tail,merchant);db.one("SELECT id FROM standard_project WHERE id=? AND status=1 AND is_deleted=0"+tail,project);db.one("SELECT id FROM merchant_project WHERE merchant_id=? AND project_id=? AND on_shelf=1 AND is_deleted=0"+tail,merchant,project);}
 Map<String,Object> source(long id,boolean lock){var first=row(id,false);shopProject(number(first,"merchant_id"),number(first,"project_id"),lock);return row(id,lock);}
 void owned(MerchantActor a,long id,boolean lock){var first=row(id,false);if(number(first,"merchant_id")!=a.merchantId())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"本店券不存在");if(lock)row(id,true);}
 Map<String,Object> view(Map<String,Object> r){var out=new LinkedHashMap<String,Object>();out.put("coupon_id",number(r,"id"));out.put("merchant_id",number(r,"merchant_id"));out.put("terms",db.parse(r.get("terms_json")));out.put("revision",number(r,"revision"));out.put("status",r.get("status"));out.put("stock_left",number(r,"total_quantity")-number(r,"issued_quantity"));out.put("publication_revision",r.get("publication_revision"));out.put("pool_selected",number(r,"pool_selected")==1);out.put("pool_revision",number(r,"pool_revision"));return out;}
 String active(){return " c.status='PUBLISHED' AND c.valid_from<=? AND c.valid_to>? AND c.issued_quantity<c.total_quantity AND c.is_deleted=0 AND EXISTS(SELECT 1 FROM merchant m WHERE m.id=c.merchant_id AND m.status=1 AND m.is_deleted=0) AND EXISTS(SELECT 1 FROM standard_project sp WHERE sp.id=s.project_id AND sp.status=1 AND sp.is_deleted=0) AND EXISTS(SELECT 1 FROM merchant_project mp WHERE mp.merchant_id=c.merchant_id AND mp.project_id=s.project_id AND mp.on_shelf=1 AND mp.is_deleted=0) AND p.coupon_id IS NOT NULL";}
 Map<String,Object> list(String where,List<Object> args,int page,int size){var count=db.jdbc.queryForObject("SELECT COUNT(*) FROM ("+SELECT+" WHERE "+where+") x",Long.class,args.toArray());var values=new ArrayList<>(args);values.add(size);values.add((page-1)*size);var items=db.jdbc.queryForList(SELECT+" WHERE "+where+" ORDER BY c.id DESC LIMIT ? OFFSET ?",values.toArray()).stream().map(this::view).toList();return page(items,count,page,size);}
 public Map<String,Object> merchantList(MerchantActor a,int page,int size){return db.reads.execute(t->{manager(a,false);return list("c.merchant_id=? AND c.is_deleted=0",List.of(a.merchantId()),page,size);});}
 public Map<String,Object> poolList(OperatorActor a,int page,int size){return db.reads.execute(t->{operators.authorize(a,OperatorIdentity.Permission.COUPON,false);return list("c.is_deleted=0 AND p.coupon_id IS NOT NULL",List.of(),page,size);});}
 public Map<String,Object> offers(VehicleOwner a,Long shop,int page,int size){return db.reads.execute(t->{db.owner(a,false);var args=new ArrayList<Object>(List.of(time(db.now()),time(db.now())));String where=active()+" AND NOT EXISTS(SELECT 1 FROM coupon_issue i WHERE i.coupon_id=c.id AND i.user_id=?)";args.add(a.id());if(shop==null)where+=" AND s.pool_selected=1";else{where+=" AND c.merchant_id=?";args.add(shop);}return list(where,args,page,size);});}
 public JsonNode create(MerchantActor a,String key,JsonNode body){CouponInput.terms(body.get("terms"));var terms=body.get("terms");return db.writes.execute(new Actor("staff_account",a.staffId()),"POST","/api/merchant/coupons",key,body,()->{manager(a,true);shopProject(a.merchantId(),terms.get("project_id").longValue(),true);},()->{
  if(!CouponInput.time(terms.get("valid_to")).isAfter(db.now()))throw CouponInput.bad();long id=db.insert("INSERT INTO coupon(merchant_id,name,amount,min_spend,total_quantity,valid_from,valid_to,status) VALUES(?,?,?,?,?,?,?,'DRAFT')",a.merchantId(),terms.get("name").textValue(),CouponInput.money(terms.get("amount")),CouponInput.money(terms.get("min_spend")),terms.get("total_quantity").intValue(),time(CouponInput.time(terms.get("valid_from"))),time(CouponInput.time(terms.get("valid_to"))));db.jdbc.update("INSERT INTO coupon_source(coupon_id,merchant_id,project_id,terms_json,revision,created_by) VALUES(?,?,?,?,1,?)",id,a.merchantId(),terms.get("project_id").longValue(),db.json(terms),a.staffId());var after=view(row(id,true));return new Change("COUPON_DRAFT_CREATE","coupon",id,Map.of(),after,after);
 });}
 public JsonNode update(MerchantActor a,long id,String key,JsonNode body){var terms=CouponInput.terms(body.get("terms"));return db.writes.execute(new Actor("staff_account",a.staffId()),"PUT","/api/merchant/coupons/"+id,key,body,()->{manager(a,true);shopProject(a.merchantId(),terms.get("project_id").longValue(),true);owned(a,id,true);},()->{var r=row(id,true);if(!"DRAFT".equals(r.get("status"))||number(r,"revision")!=body.get("expected_revision").longValue()||!CouponInput.time(terms.get("valid_to")).isAfter(db.now()))throw conflict();var before=view(r);db.jdbc.update("UPDATE coupon SET name=?,amount=?,min_spend=?,total_quantity=?,valid_from=?,valid_to=? WHERE id=?",terms.get("name").textValue(),CouponInput.money(terms.get("amount")),CouponInput.money(terms.get("min_spend")),terms.get("total_quantity").intValue(),time(CouponInput.time(terms.get("valid_from"))),time(CouponInput.time(terms.get("valid_to"))),id);db.jdbc.update("UPDATE coupon_source SET project_id=?,terms_json=?,revision=revision+1 WHERE coupon_id=?",terms.get("project_id").longValue(),db.json(terms),id);var after=view(row(id,true));return new Change("COUPON_DRAFT_UPDATE","coupon",id,before,after,after);});}
 public JsonNode status(MerchantActor a,long id,String key,JsonNode body){return db.writes.execute(new Actor("staff_account",a.staffId()),"PUT","/api/merchant/coupons/"+id+"/status",key,body,()->{manager(a,true);owned(a,id,false);if("PUBLISHED".equals(body.path("status").asText()))source(id,true);else row(id,true);},()->{var r=row(id,true);String target=body.path("status").asText();if(number(r,"revision")!=body.get("expected_revision").longValue()||!(target.equals("PUBLISHED")?r.get("status").equals("DRAFT"):r.get("status").equals("PUBLISHED")))throw conflict();if(target.equals("PUBLISHED")){if(!instant(r.get("valid_to")).isAfter(db.now()))throw conflict();db.jdbc.update("INSERT INTO coupon_publication(coupon_id,revision,terms_json,published_by,published_at) VALUES(?,?,?,?,?)",id,number(r,"revision")+1,r.get("terms_json").toString(),a.staffId(),time(db.now()));}var before=view(r);db.jdbc.update("UPDATE coupon SET status=? WHERE id=?",target,id);db.jdbc.update("UPDATE coupon_source SET revision=revision+1 WHERE coupon_id=?",id);var after=view(row(id,true));return new Change("COUPON_STATUS_SET","coupon",id,before,after,after);});}
 public JsonNode pool(OperatorActor a,long id,String key,JsonNode body){return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/coupons/"+id+"/pool",key,body,()->{operators.authorize(a,OperatorIdentity.Permission.COUPON,true);if(body.get("selected").booleanValue()){var r=source(id,true);if(!"PUBLISHED".equals(r.get("status"))||r.get("publication_revision")==null||!instant(r.get("valid_to")).isAfter(db.now()))throw conflict();}else{var r=row(id,false);db.lockShop(number(r,"merchant_id"));row(id,true);}},()->{var r=row(id,true);if(number(r,"pool_revision")!=body.get("expected_pool_revision").longValue())throw conflict();var before=view(r);db.jdbc.update("UPDATE coupon_source SET pool_selected=?,pool_revision=pool_revision+1 WHERE coupon_id=?",body.get("selected").booleanValue(),id);var after=view(row(id,true));return new Change("COUPON_POOL_SET","coupon",id,before,after,after);});}
 public JsonNode claim(VehicleOwner a,String key,JsonNode body){long id=body.get("coupon_id").longValue();return db.writes.execute(new Actor("user",a.id()),"POST","/api/coupon/receive",key,body,()->{db.owner(a,true);var r=source(id,true);if(!"PUBLISHED".equals(r.get("status"))||r.get("publication_revision")==null||number(r,"publication_revision")!=body.get("publication_revision").longValue()||instant(r.get("valid_from")).isAfter(db.now())||!instant(r.get("valid_to")).isAfter(db.now()))throw conflict();},()->{var r=row(id,true);if(number(r,"issued_quantity")>=number(r,"total_quantity")||!db.jdbc.queryForList("SELECT user_coupon_id FROM coupon_issue WHERE coupon_id=? AND user_id=?",id,a.id()).isEmpty())throw conflict();var before=view(r);long uc=db.insert("INSERT INTO user_coupon(user_id,coupon_id,status) VALUES(?,?,'AVAILABLE')",a.id(),id);db.jdbc.update("INSERT INTO coupon_issue(user_coupon_id,coupon_id,user_id,publication_revision,issued_at) VALUES(?,?,?,?,?)",uc,id,a.id(),number(r,"publication_revision"),time(db.now()));db.jdbc.update("UPDATE coupon SET issued_quantity=issued_quantity+1 WHERE id=?",id);db.jdbc.update("INSERT INTO coupon_stock_event(coupon_id,user_coupon_id,quantity_delta,stock_after,occurred_at) VALUES(?,?,-1,?,?)",id,uc,number(r,"total_quantity")-number(r,"issued_quantity")-1,time(db.now()));var after=view(row(id,true));return new Change("COUPON_CLAIM","coupon",id,before,after,Map.of("user_coupon_id",uc,"coupon_id",id,"publication_revision",number(r,"publication_revision")));});}
 public Map<String,Object> mine(VehicleOwner a,int page,int size){return db.reads.execute(t->{db.owner(a,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM user_coupon WHERE user_id=? AND is_deleted=0",Long.class,a.id());var rows=db.jdbc.queryForList("SELECT u.id,u.coupon_id,u.status,u.order_id,u.used_at,i.publication_revision,p.terms_json,c.merchant_id,m.status AS merchant_status,m.is_deleted AS merchant_deleted FROM user_coupon u LEFT JOIN coupon_issue i ON i.user_coupon_id=u.id AND i.user_id=u.user_id AND i.coupon_id=u.coupon_id LEFT JOIN coupon_publication p ON p.coupon_id=i.coupon_id AND p.revision=i.publication_revision LEFT JOIN coupon c ON c.id=u.coupon_id LEFT JOIN merchant m ON m.id=c.merchant_id WHERE u.user_id=? AND u.is_deleted=0 ORDER BY u.id DESC LIMIT ? OFFSET ?",a.id(),size,(page-1)*size);var items=rows.stream().map(r->{var out=new LinkedHashMap<String,Object>();boolean known=r.get("terms_json")!=null;var terms=db.parse(r.get("terms_json"));String availability="UNKNOWN";if(known){availability="AVAILABLE";if(CouponInput.time(terms.get("valid_from")).isAfter(db.now()))availability="NOT_STARTED";else if(!CouponInput.time(terms.get("valid_to")).isAfter(db.now()))availability="EXPIRED";else if(!Objects.equals(r.get("merchant_status"),1)||!Objects.equals(r.get("merchant_deleted"),0))availability="ISSUER_UNAVAILABLE";}out.put("user_coupon_id",number(r,"id"));out.put("coupon_id",number(r,"coupon_id"));out.put("merchant_id",r.get("merchant_id"));out.put("source_known",known);out.put("terms",known?terms:null);out.put("status",r.get("status"));out.put("availability",availability);out.put("publication_revision",known?r.get("publication_revision"):null);return out;}).toList();return page(items,count,page,size);});}
}
